		this.baseStation = baseStation;
		currentTarget = new LlaCoordinate(0, 0, 0);
		try {
			droneID = drnName;
			baseStation.setStatusCallbackNotifier(droneID, this);
			droneStatus.setGroundstationId(baseStation.getHandlerId());
		} catch (Exception e) {
			LOGGER.error(e);
		}
